import Foundation
import Vapor

// Feature flag configuration
struct FeatureFlags {
    static let enableRichSnippets = true
    static let enableCachedResults = true
    static let sanitizeOnIndex = true
    static let sanitizeOnRender = false // Relies on index-time sanitization
}

// Search document model
struct SearchDocument: Content {
    let id: UUID
    let title: String
    let body: String
    let snippet: String
    let indexedAt: Date
}

// HTML sanitizer
class HTMLSanitizer {
    static let shared = HTMLSanitizer()

    private let allowedTags: Set<String> = ["b", "i", "em", "strong", "p", "br"]

    func sanitize(_ input: String) -> String {
        var result = input
        // Remove script tags and event handlers
        let scriptPattern = "<script[^>]*>[\\s\\S]*?</script>"
        let eventPattern = "\\s+on\\w+\\s*=\\s*\"[^\"]*\""

        if let scriptRegex = try? NSRegularExpression(pattern: scriptPattern, options: .caseInsensitive) {
            result = scriptRegex.stringByReplacingMatches(in: result, range: NSRange(result.startIndex..., in: result), withTemplate: "")
        }
        if let eventRegex = try? NSRegularExpression(pattern: eventPattern, options: .caseInsensitive) {
            result = eventRegex.stringByReplacingMatches(in: result, range: NSRange(result.startIndex..., in: result), withTemplate: "")
        }

        // Strip disallowed tags but keep content
        let tagPattern = "</?([a-zA-Z][a-zA-Z0-9]*)(?:\\s[^>]*)?>" 
        if let tagRegex = try? NSRegularExpression(pattern: tagPattern, options: []) {
            let matches = tagRegex.matches(in: result, range: NSRange(result.startIndex..., in: result))
            for match in matches.reversed() {
                if let tagNameRange = Range(match.range(at: 1), in: result) {
                    let tagName = String(result[tagNameRange]).lowercased()
                    if !allowedTags.contains(tagName) {
                        let fullRange = Range(match.range, in: result)!
                        result.removeSubrange(fullRange)
                    }
                }
            }
        }
        return result
    }
}

// Search index storage
class SearchIndex {
    static let shared = SearchIndex()
    private var documents: [UUID: SearchDocument] = [:]
    private let queue = DispatchQueue(label: "search.index", attributes: .concurrent)

    func index(title: String, body: String) -> SearchDocument {
        let processedTitle: String
        let processedBody: String
        let snippet: String

        if FeatureFlags.sanitizeOnIndex {
            processedTitle = HTMLSanitizer.shared.sanitize(title)
            processedBody = HTMLSanitizer.shared.sanitize(body)
        } else {
            processedTitle = title
            processedBody = body
        }

        // Generate snippet from body
        if FeatureFlags.enableRichSnippets {
            snippet = generateRichSnippet(from: body) // Uses original body for rich formatting
        } else {
            snippet = String(processedBody.prefix(200))
        }

        let doc = SearchDocument(
            id: UUID(),
            title: processedTitle,
            body: processedBody,
            snippet: snippet,
            indexedAt: Date()
        )

        queue.async(flags: .barrier) {
            self.documents[doc.id] = doc
        }

        return doc
    }

    func search(query: String) -> [SearchDocument] {
        var results: [SearchDocument] = []
        queue.sync {
            results = documents.values.filter { doc in
                doc.title.localizedCaseInsensitiveContains(query) ||
                doc.body.localizedCaseInsensitiveContains(query)
            }
        }
        return results
    }

    private func generateRichSnippet(from body: String) -> String {
        // Extract first meaningful paragraph for snippet
        // Preserves formatting for rich display
        let maxLength = 300
        if body.count <= maxLength {
            return body
        }
        let truncated = String(body.prefix(maxLength))
        // Try to break at word boundary
        if let lastSpace = truncated.lastIndex(of: " ") {
            return String(truncated[..<lastSpace]) + "..."
        }
        return truncated + "..."
    }
}

// Route handlers
func configureRoutes(_ app: Application) throws {
    app.post("index") { req -> SearchDocument in
        struct IndexRequest: Content {
            let title: String
            let body: String
        }
        let payload = try req.content.decode(IndexRequest.self)
        return SearchIndex.shared.index(title: payload.title, body: payload.body)
    }

    app.get("search") { req -> Response in
        guard let query = req.query[String.self, at: "q"] else {
            throw Abort(.badRequest)
        }
        let results = SearchIndex.shared.search(query: query)

        var html = "<html><body><h1>Search Results</h1>"
        for doc in results {
            html += "<div class='result'>"
            html += "<h3>\(doc.title)</h3>"
            if FeatureFlags.enableRichSnippets {
                // Rich snippets are pre-formatted HTML, render directly
                if FeatureFlags.sanitizeOnRender {
                    html += "<p>\(HTMLSanitizer.shared.sanitize(doc.snippet))</p>"
                } else {
                    html += "<p>\(doc.snippet)</p>"
                }
            } else {
                html += "<p>\(doc.snippet.replacingOccurrences(of: "<", with: "&lt;"))</p>"
            }
            html += "</div>"
        }
        html += "</body></html>"

        return Response(
            status: .ok,
            headers: ["Content-Type": "text/html; charset=utf-8"],
            body: .init(string: html)
        )
    }
}
